package io.github.turbopro.ism.operation.task;
import io.github.turbopro.ism.common.infrastructure.tenant.TenantScopedMapper;import io.github.turbopro.ism.operation.OperationModels;import org.apache.ibatis.annotations.*;import java.util.*;
@Mapper public interface TaskCenterMapper extends TenantScopedMapper{
 @Select("SELECT id,tenant_id,task_no,task_type,requester_id,request_payload,status,progress,lease_owner,lease_until,retry_count,version,current_stage,cancel_requested,result_file_id,error_code,error_message,created_at,started_at,finished_at FROM ops_async_task WHERE tenant_id=#{tenantId} AND requester_id=#{userId} ORDER BY created_at DESC,id DESC LIMIT 200")List<OperationModels.AsyncTask> tasks(long tenantId,long userId);
 @Select("SELECT id,tenant_id,task_no,task_type,requester_id,request_payload,status,progress,lease_owner,lease_until,retry_count,version,current_stage,cancel_requested,result_file_id,error_code,error_message,created_at,started_at,finished_at FROM ops_async_task WHERE tenant_id=#{tenantId} AND requester_id=#{userId} AND id=#{id}")OperationModels.AsyncTask task(long tenantId,long userId,long id);
 @Update("UPDATE ops_async_task SET status=CASE WHEN status='QUEUED' THEN 'CANCELLED' ELSE status END,cancel_requested=1,finished_at=CASE WHEN status='QUEUED' THEN CURRENT_TIMESTAMP(3) ELSE finished_at END,version=version+1 WHERE tenant_id=#{tenantId} AND requester_id=#{userId} AND id=#{id} AND status IN ('QUEUED','RUNNING') AND version=#{version}")int cancel(long tenantId,long userId,long id,int version);
 @Update("UPDATE ops_async_task SET status='QUEUED',progress=0,current_stage=NULL,cancel_requested=0,error_code=NULL,error_message=NULL,lease_owner=NULL,lease_until=NULL,started_at=NULL,finished_at=NULL,version=version+1 WHERE tenant_id=#{tenantId} AND requester_id=#{userId} AND id=#{id} AND status IN ('FAILED','CANCELLED') AND retry_count<3 AND version=#{version}")int retry(long tenantId,long userId,long id,int version);
}
